.tool-app-fencefleet .ff-pill-active { background: #dcfce7; color: #166534; }
.tool-app-fencefleet .ff-pill-closed { background: #f1f5f9; color: #475569; }
.tool-app-fencefleet .ff-pill-pickup { background: #fef3c7; color: #92400e; }
