.tool-app-fencefleet .ff-action-panel { margin-top: 10px; background: #faf9ff; border: 1px dashed #c4b5fd; border-radius: 10px; padding: 12px; }
.tool-app-fencefleet .ff-action-panel .ff-form { margin: 0; padding: 0; border: none; background: none; }
.tool-app-fencefleet .ff-callout { background: #f5f3ff; border: 1px solid #ddd6fe; border-radius: 12px; padding: 14px; font-size: 14px; }
.tool-app-fencefleet .ff-callout .ff-total { font-size: 22px; font-weight: 800; color: #6d28d9; }
