.tool-app-fencefleet .ff-table th { text-align: left; font-size: 11px; text-transform: uppercase; letter-spacing: 0.05em; color: #6d6d8f; padding: 6px 8px; border-bottom: 2px solid #e9e4fb; }
.tool-app-fencefleet .ff-table td { padding: 7px 8px; border-bottom: 1px solid #f1eefc; }
.tool-app-fencefleet .ff-empty { color: #8a8aa3; font-size: 14px; background: #faf9ff; border: 1px dashed #ddd6fe; border-radius: 12px; padding: 16px; text-align: center; }
.tool-app-fencefleet .ff-printdoc { display: none; }
@media print {
  .tool-app-fencefleet .ff-screen { display: none !important; }
  .tool-app-fencefleet .ff-printdoc { display: block !important; color: #000; font-size: 14px; }
  .tool-app-fencefleet .ff-printdoc h1 { font-size: 22px; margin: 0 0 4px; }
  .tool-app-fencefleet .ff-printdoc table { width: 100%; border-collapse: collapse; margin: 12px 0; }
  .tool-app-fencefleet .ff-printdoc th, .tool-app-fencefleet .ff-printdoc td { border: 1px solid #999; padding: 6px 8px; text-align: left; font-size: 13px; }
  .tool-app-fencefleet .ff-printdoc .ff-ptotal { font-size: 18px; font-weight: 800; }
}
@media (max-width: 560px) {
  .tool-app-fencefleet .ff-sec-head { flex-direction: column; align-items: stretch; gap: 8px; }
  .tool-app-fencefleet .ff-actions .ff-btn { flex: 1 1 auto; }
}

app_js:
(function () {
  'use strict';
  function $(id) { return document.getElementById(id); }
  function esc(s) {
    return String(s == null ? '' : s).replace(/[&<>"']/g, function (c) {
      return { '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' }[c];
    });
  }
  function money(n) { n = parseFloat(n); return '$' + (isFinite(n) ? n : 0).toFixed(2); }
  function num(v, dflt) { var n = parseFloat(v); return isFinite(n) ? n : dflt; }
  function int(v, dflt) { var n = parseInt(v, 10); return isFinite(n) ? n : dflt; }
  function uid() { return 'h' + Date.now().toString(36) + Math.floor(Math.random() * 1e6).toString(36); }
  function parseDate(s) {
    var p = String(s || '').split('-');
    if (p.length !== 3) return null;
    var d = new Date(parseInt(p[0], 10), parseInt(p[1], 10) - 1, parseInt(p[2], 10));
    return isNaN(d.getTime()) ? null : d;
  }
  function fmtDate(s) {
    var d = parseDate(s);
    if (!d) return '';
    return d.toLocaleDateString('en-US', { month: 'short', day: 'numeric', year: 'numeric' });
  }
  function todayStr() {
    var d = new Date();
    return d.getFullYear() + '-' + String(d.getMonth() + 1).padStart(2, '0') + '-' + String(d.getDate()).padStart(2, '0');
  }
  function daysBetween(a, b) {
    var da = parseDate(a), db = parseDate(b);
    if (!da || !db) return 0;
    return Math.max(0, Math.round((db.getTime() - da.getTime()) / 864e5));
  }

  var LS_KEY = 'toolapp-fencefleet-v1';
  function defaults() {
    return { biz: '', inventory: { panels: 200, feet: 220, clamps: 400 }, replace: 85, hires: [] };
  }
  function load() {
    try {
      var s = JSON.parse(localStorage.getItem(LS_KEY));
      if (s && s.inventory && Array.isArray(s.hires)) {
        s.biz = s.biz || '';
        s.replace = num(s.replace, 85);
        return s;
      }
    } catch (e) {}
    return defaults();
  }
  var state = load();
  function save() {
    try { localStorage.setItem(LS_KEY, JSON.stringify(state)); } catch (e) {}
  }

  // Exact hire economics: sweep deliveries (+) and returns (-) over time.
  // cost = rate/28 * sum(qtyOut_segment * days). asOf caps billing (close date or today).
  function hirePosition(hire, asOf) {
    var evs = [];
    (hire.deliveries || []).forEach(function (d) {
      if (d.date && d.qty > 0) evs.push({ date: d.date, q: d.qty });
    });
    (hire.returns || []).forEach(function (r) {
      if (r.date && r.qty > 0) evs.push({ date: r.date, q: -r.qty });
    });
    evs = evs.filter(function (e) { return e.date <= asOf; });
    evs.sort(function (a, b) {
      if (a.date !== b.date) return a.date < b.date ? -1 : 1;
      return b.q - a.q; // deliveries before returns on the same day
    });
    var qty = 0, costDays = 0, prev = null, first = evs.length ? evs[0].date : null;
    evs.forEach(function (e) {
      if (prev && e.date > prev) costDays += qty * daysBetween(prev, e.date);
      qty += e.q;
      prev = e.date;
    });
    if (prev && asOf > prev) costDays += qty * daysBetween(prev, asOf);
    if (qty < 0) qty = 0;
    var rate = num(hire.rate, 0);
    return {
      qtyOut: qty,
      daysOut: first ? daysBetween(first, asOf) : 0,
      cost: costDays * rate / 28,
      firstDate: first
    };
  }
  function qtyOutAt(hire, dateStr) {
    var q = 0;
    (hire.deliveries || []).forEach(function (d) { if (d.date <= dateStr) q += d.qty; });
    (hire.returns || []).forEach(function (r) { if (r.date <= dateStr) q -= r.qty; });
    return Math.max(0, q);
  }
  function activeHires() { return state.hires.filter(function (h) { return h.status === 'active'; }); }
  function asOfFor(hire) { return hire.status === 'closed' && hire.closedAt ? hire.closedAt : todayStr(); }
  function lostCost(hire) {
    var n = 0;
    (hire.returns || []).forEach(function (r) { n += int(r.lost, 0); });
    return n * num(state.replace, 0);
  }
  function fleetStats() {
    var act = activeHires();
    var panelsOut = 0, feetOut = 0, clampsOut = 0, panelsLost = 0, unbilled = 0;
    act.forEach(function (h) {
      var p = hirePosition(h, todayStr());
      panelsOut += p.qtyOut;
      unbilled += p.cost;
      feetOut += int(h.feet, 0);
      clampsOut += int(h.clamps, 0);
    });
    state.hires.forEach(function (h) {
      (h.returns || []).forEach(function (r) { panelsLost += int(r.lost, 0); });
    });
    var inv = state.inventory;
    return {
      panels: { owned: int(inv.panels, 0), out: panelsOut, lost: panelsLost },
      feet: { owned: int(inv.feet, 0), out: feetOut },
      clamps: { owned: int(inv.clamps, 0), out: clampsOut },
      activeCount: act.length, unbilled: unbilled
    };
  }

  function card(k, v, s, moneyCls) {
    return '<div class="ff-card' + (moneyCls ? ' ff-money' : '') + '"><div class="ff-k">' + esc(k) +
      '</div><div class="ff-v">' + esc(v) + '</div><div class="ff-s">' + esc(s) + '</div></div>';
  }
  function renderFleet() {
    var f = fleetStats();
    var pAvail = f.panels.owned - f.panels.out - f.panels.lost;
    $('ff-fleet').innerHTML =
      card('Panels out', f.panels.out, 'of ' + f.panels.owned + ' owned · ' + pAvail + ' available · ' + f.panels.lost + ' lost') +
      card('Feet out', f.feet.out, 'of ' + f.feet.owned + ' owned · ' + (f.feet.owned - f.feet.out) + ' available') +
      card('Clamps out', f.clamps.out, 'of ' + f.clamps.owned + ' owned · ' + (f.clamps.owned - f.clamps.out) + ' available') +
      card('Active hires', f.activeCount, 'sites with fence out') +
      card('Unbilled hire $', money(f.unbilled), 'accrued through today', true);
  }

  function batchesHtml(hire) {
    var bits = [];
    (hire.deliveries || []).forEach(function (d, i) {
      bits.push((i === 0 ? 'Delivered ' : '+ ') + d.qty + ' panels — ' + fmtDate(d.date));
    });
    (hire.returns || []).forEach(function (r) {
      bits.push('Returned ' + r.qty + ' panels — ' + fmtDate(r.date) + (r.lost > 0 ? ' (' + r.lost + ' lost/damaged)' : ''));
    });
    return bits.length ? '<div class="ff-batches">' + esc(bits.join(' · ')) + '</div>' : '';
  }
  function actionPanelHtml(hire, kind) {
    var t = todayStr();
    if (kind === 'add') {
      return '<div class="ff-action-panel"><form class="ff-form" data-ff-act="add" data-ff-id="' + hire.id + '">' +
        '<label>Extra panels<input type="number" min="1" step="1" value="10" data-ff-f="qty" required></label>' +
        '<label>Date delivered<input type="date" value="' + t + '" data-ff-f="date" required></label>' +
        '<div class="ff-span2 ff-form-actions"><button class="ff-btn ff-btn-sm" type="submit">Record delivery</button></div></form></div>';
    }
    if (kind === 'return') {
      return '<div class="ff-action-panel"><form class="ff-form" data-ff-act="return" data-ff-id="' + hire.id + '">' +
        '<label>Panels returned<input type="number" min="1" step="1" data-ff-f="qty" required></label>' +
        '<label>Return date<input type="date" value="' + t + '" data-ff-f="date" required></label>' +
        '<label>Lost / damaged<input type="number" min="0" step="1" value="0" data-ff-f="lost"></label>' +
        '<div class="ff-span2 ff-form-actions"><button class="ff-btn ff-btn-sm" type="submit">Record return</button></div></form></div>';
    }
    if (kind === 'pickup') {
      return '<div class="ff-action-panel"><form class="ff-form" data-ff-act="pickup" data-ff-id="' + hire.id + '">' +
        '<label>Scheduled pickup<input type="date" value="' + (hire.pickup || t) + '" data-ff-f="date" required></label>' +
        '<div class="ff-span2 ff-form-actions"><button class="ff-btn ff-btn-sm" type="submit">Save pickup</button>' +
        (hire.pickup ? ' <button class="ff-btn ff-btn-sm ff-btn-ghost" type="button" data-ff-clearpickup="' + hire.id + '">Clear</button>' : '') +
        '</div></form></div>';
    }
    if (kind === 'close') {
      return '<div class="ff-action-panel"><p style="margin:0 0 10px;font-size:14px">Close this hire? Billing stops today and a final invoice is prepared.</p>' +
        '<button class="ff-btn ff-btn-sm ff-btn-danger" type="button" data-ff-close="' + hire.id + '">Close hire &amp; print invoice</button></div>';
    }
    return '';
  }
  var openAction = {}; // hireId -> kind

  function hireCard(hire) {
    var p = hirePosition(hire, asOfFor(hire));
    var pill = hire.status === 'closed'
      ? '<span class="ff-pill ff-pill-closed">CLOSED</span>'
      : '<span class="ff-pill ff-pill-active">ACTIVE</span>';
    var pickup = hire.pickup && hire.status === 'active'
      ? '<span class="ff-pill ff-pill-pickup">PICKUP ' + esc(fmtDate(hire.pickup)) + '</span>' : '';
    var html = '<div class="ff-hire"><div class="ff-hire-head"><div><b>' + esc(hire.site) + '</b>' +
      (hire.contact ? '<div style="font-size:12px;color:#6d6d8f">' + esc(hire.contact) + '</div>' : '') + '</div>' +
      '<div>' + pill + ' ' + pickup + '</div></div>' +
      '<div class="ff-hire-meta">' +
      '<div class="ff-m"><div class="ff-k">Panels out</div><div class="ff-v">' + p.qtyOut + '</div></div>' +
      '<div class="ff-m"><div class="ff-k">Days out</div><div class="ff-v">' + p.daysOut + '</div></div>' +
      '<div class="ff-m"><div class="ff-k">Hire cost' + (hire.status === 'active' ? ' to date' : '') + '</div><div class="ff-v">' + money(p.cost) + '</div></div>' +
      '<div class="ff-m"><div class="ff-k">Rate</div><div class="ff-v">' + money(hire.rate) + '<span style="font-size:11px;font-weight:600"> /28d</span></div></div>' +
      '</div>' + batchesHtml(hire);
    if (hire.notes) html += '<div style="font-size:12px;color:#6d6d8f;margin:4px 0">Notes: ' + esc(hire.notes) + '</div>';
    if (hire.status === 'active') {
      html += '<div class="ff-actions">' +
        '<button class="ff-btn ff-btn-sm ff-btn-ghost" type="button" data-ff-action="add" data-ff-id="' + hire.id + '">+ Panels</button>' +
        '<button class="ff-btn ff-btn-sm ff-btn-ghost" type="button" data-ff-action="return" data-ff-id="' + hire.id + '">Record return</button>' +
        '<button class="ff-btn ff-btn-sm ff-btn-ghost" type="button" data-ff-action="pickup" data-ff-id="' + hire.id + '">Pickup date</button>' +
        '<button class="ff-btn ff-btn-sm" type="button" data-ff-action="invoice" data-ff-id="' + hire.id + '">Invoice</button>' +
        '<button class="ff-btn ff-btn-sm ff-btn-danger" type="button" data-ff-action="close" data-ff-id="' + hire.id + '">Close hire</button>' +
        '</div>';
      if (openAction[hire.id]) html += actionPanelHtml(hire, openAction[hire.id]);
    } else {
      html += '<div class="ff-actions"><button class="ff-btn ff-btn-sm ff-btn-ghost" type="button" data-ff-action="invoice" data-ff-id="' + hire.id + '">Reprint invoice</button></div>';
    }
    return html + '</div>';
  }

  function renderHires() {
    var act = activeHires();
    var el = $('ff-hires');
    if (!act.length) {
      el.innerHTML = '<div class="ff-empty">No active hires. Add one when panels leave the yard.</div>';
    } else {
      act.sort(function (a, b) { return a.createdAt < b.createdAt ? -1 : 1; });
      el.innerHTML = act.map(hireCard).join('');
    }
    var closed = state.hires.filter(function (h) { return h.status === 'closed'; });
    var cel = $('ff-closed');
    if (!closed.length) {
      cel.innerHTML = '<div class="ff-empty">No closed hires yet.</div>';
    } else {
      closed.sort(function (a, b) { return (b.closedAt || '') < (a.closedAt || '') ? -1 : 1; });
      cel.innerHTML = closed.map(hireCard).join('');
    }
  }

  function renderLosses() {
    var rows = [];
    state.hires.forEach(function (h) {
      (h.returns || []).forEach(function (r) {
        if (int(r.lost, 0) > 0) rows.push({ date: r.date, site: h.site, lost: int(r.lost, 0) });
      });
    });
    rows.sort(function (a, b) { return a.date < b.date ? -1 : 1; });
    var tb = $('ff-losses');
    if (!rows.length) {
      tb.innerHTML = '<tr><td colspan="4" style="color:#8a8aa3">No lost or damaged panels recorded. Good.</td></tr>';
      return;
    }
    var total = 0;
    tb.innerHTML = rows.map(function (r) {
      var c = r.lost * num(state.replace, 0);
      total += c;
      return '<tr><td>' + esc(fmtDate(r.date)) + '</td><td>' + esc(r.site) + '</td><td>' + r.lost + '</td><td>' + money(c) + '</td></tr>';
    }).join('') + '<tr><td colspan="3"><b>Total replacement cost</b></td><td><b>' + money(total) + '</b></td></tr>';
  }

  function renderInventory() {
    $('ff-inv-biz').value = state.biz || '';
    $('ff-inv-panels').value = int(state.inventory.panels, 0);
    $('ff-inv-feet').value = int(state.inventory.feet, 0);
    $('ff-inv-clamps').value = int(state.inventory.clamps, 0);
    $('ff-inv-replace').value = num(state.replace, 0);
  }

  function renderAll() { renderFleet(); renderHires(); renderLosses(); }

  function getHire(id) {
    for (var i = 0; i < state.hires.length; i++) if (state.hires[i].id === id) return state.hires[i];
    return null;
  }

  function printInvoice(hire) {
    var p = hirePosition(hire, asOfFor(hire));
    var lc = lostCost(hire);
    var rows = '';
    (hire.deliveries || []).forEach(function (d) {
      rows += '<tr><td>Delivery — ' + d.qty + ' panels</td><td>' + esc(fmtDate(d.date)) + '</td><td>' + money(hire.rate) + ' / 28 days</td></tr>';
    });
    (hire.returns || []).forEach(function (r) {
      rows += '<tr><td>Return — ' + r.qty + ' panels' + (r.lost > 0 ? ' (' + r.lost + ' lost/damaged)' : '') + '</td><td>' + esc(fmtDate(r.date)) + '</td><td></td></tr>';
    });
    $('ff-printdoc').innerHTML =
      '<h1>' + esc(state.biz || 'FenceFleet hire invoice') + '</h1>' +
      '<p><strong>Site:</strong> ' + esc(hire.site) + (hire.contact ? '<br><strong>Contact:</strong> ' + esc(hire.contact) : '') +
      '<br><strong>Hire period:</strong> ' + esc(fmtDate(p.firstDate)) + ' — ' + esc(fmtDate(asOfFor(hire))) + ' (' + p.daysOut + ' days)' +
      (hire.status === 'closed' ? '<br><strong>Status:</strong> Closed' : '') + '</p>' +
      '<table><thead><tr><th>Event</th><th>Date</th><th>Rate</th></tr></thead><tbody>' + rows + '</tbody></table>' +
      '<p><strong>Hire cost (' + p.daysOut + ' days, pro-rata):</strong> ' + money(p.cost) + '<br>' +
      (lc > 0 ? '<strong>Lost/damaged panels:</strong> ' + money(lc) + '<br>' : '') +
      '<span class="ff-ptotal">Total due: ' + money(p.cost + lc) + '</span></p>' +
      (hire.notes ? '<p><strong>Notes:</strong> ' + esc(hire.notes) + '</p>' : '');
    window.print();
  }

  function calcQuote() {
    var panels = int($('ff-c-panels').value, 0);
    var start = $('ff-c-start').value, end = $('ff-c-end').value;
    var rate = num($('ff-c-rate').value, 0);
    var out = $('ff-calc-out');
    var days = daysBetween(start, end);
    if (panels <= 0 || !start || !end || days <= 0 || rate < 0) { out.hidden = true; return; }
    var cycles = Math.floor(days / 28), rem = days % 28;
    var total = panels * rate * days / 28;
    out.hidden = false;
    out.innerHTML = '<div><b>' + panels + ' panels × ' + days + ' days</b> (' + fmtDate(start) + ' — ' + fmtDate(end) + ')<br>' +
      'That is ' + cycles + ' full 28-day cycle' + (cycles === 1 ? '' : 's') + (rem ? ' + ' + rem + ' pro-rata days' : '') +
      ' at ' + money(rate) + ' per panel.</div>' +
      '<div class="ff-total">' + money(total) + '</div>';
  }

  var root = $('toolAppRoot');

  $('ff-toggle-new').addEventListener('click', function () {
    var f = $('ff-newhire');
    f.hidden = !f.hidden;
    if (!f.hidden && !$('ff-nh-date').value) $('ff-nh-date').value = todayStr();
  });

  $('ff-newhire').addEventListener('submit', function (e) {
    e.preventDefault();
    var site = $('ff-nh-site').value.trim();
    if (!site) return;
    state.hires.push({
      id: uid(), site: site, contact: $('ff-nh-contact').value.trim(),
      rate: num($('ff-nh-rate').value, 0),
      deliveries: [{ qty: Math.max(1, int($('ff-nh-panels').value, 1)), date: $('ff-nh-date').value || todayStr() }],
      returns: [], feet: Math.max(0, int($('ff-nh-feet').value, 0)), clamps: Math.max(0, int($('ff-nh-clamps').value, 0)),
      pickup: null, notes: $('ff-nh-notes').value.trim(), status: 'active', createdAt: Date.now()
    });
    save(); renderAll();
    e.target.reset(); e.target.hidden = true;
  });

  $('ff-inventory').addEventListener('submit', function (e) {
    e.preventDefault();
    state.biz = $('ff-inv-biz').value.trim();
    state.inventory = {
      panels: Math.max(0, int($('ff-inv-panels').value, 0)),
      feet: Math.max(0, int($('ff-inv-feet').value, 0)),
      clamps: Math.max(0, int($('ff-inv-clamps').value, 0))
    };
    state.replace = Math.max(0, num($('ff-inv-replace').value, 0));
    save(); renderAll(); renderLosses();
  });

  root.addEventListener('input', function (e) {
    if (e.target && e.target.id && e.target.id.indexOf('ff-c-') === 0) calcQuote();
  });

  root.addEventListener('submit', function (e) {
    var form = e.target;
    if (!form.getAttribute || !form.getAttribute('data-ff-act')) return;
    e.preventDefault();
    var hire = getHire(form.getAttribute('data-ff-id'));
    if (!hire) return;
    var kind = form.getAttribute('data-ff-act');
    function field(n) { var el = form.querySelector('[data-ff-f="' + n + '"]'); return el ? el.value : ''; }
    if (kind === 'add') {
      var q = int(field('qty'), 0), d = field('date') || todayStr();
      if (q > 0 && parseDate(d)) { hire.deliveries.push({ qty: q, date: d }); }
    } else if (kind === 'return') {
      var rq = int(field('qty'), 0), rd = field('date') || todayStr(), lost = Math.max(0, int(field('lost'), 0));
      var avail = qtyOutAt(hire, rd);
      if (rq > 0 && rq <= avail && parseDate(rd)) {
        hire.returns.push({ qty: rq, date: rd, lost: Math.min(lost, rq) });
      }
    } else if (kind === 'pickup') {
      var pd = field('date');
      if (parseDate(pd)) hire.pickup = pd;
    }
    openAction[hire.id] = null;
    save(); renderAll();
  });

  root.addEventListener('click', function (e) {
    var t = e.target;
    if (t.hasAttribute && t.hasAttribute('data-ff-clearpickup')) {
      var h1 = getHire(t.getAttribute('data-ff-clearpickup'));
      if (h1) { h1.pickup = null; openAction[h1.id] = null; save(); renderAll(); }
      return;
    }
    if (t.hasAttribute && t.hasAttribute('data-ff-close')) {
      var h2 = getHire(t.getAttribute('data-ff-close'));
      if (h2) {
        h2.status = 'closed'; h2.closedAt = todayStr();
        openAction[h2.id] = null; save(); renderAll(); printInvoice(h2);
      }
      return;
    }
    if (t.hasAttribute && t.hasAttribute('data-ff-action')) {
      var id = t.getAttribute('data-ff-id'), kind = t.getAttribute('data-ff-action');
      var hire = getHire(id);
      if (!hire) return;
      if (kind === 'invoice') { printInvoice(hire); return; }
      openAction[id] = (openAction[id] === kind) ? null : kind;
      renderHires();
    }
  });

  (function init() {
    var t = todayStr();
    $('ff-nh-date').value = t;
    $('ff-c-start').value = t;
    $('ff-c-end').value = t;
    renderInventory();
    renderAll();
    calcQuote();
  })();
})();
